from flask import Flask, jsonify
import os

app = Flask(__name__)

@app.errorhandler(Exception)
def handle_exception(e):
    return jsonify({""message"": ""An unexpected error occurred.""}), 500

@app.errorhandler(404)
def not_found(e):
    return jsonify({""message"": ""Resource not found.""}), 404

@app.errorhandler(401)
def unauthorized(e):
    return jsonify({""message"": ""Unauthorized access.""}), 401

# Set up database connection using environment variables
DATABASE_URL = os.getenv(""DATABASE_URL"")
app.config[""SQLALCHEMY_DATABASE_URI""] = DATABASE_URL

# Configure authentication middleware
AUTHENTICATION_ENABLED = os.getenv(""AUTHENTICATION_ENABLED"", ""false"").lower() == ""true""
if AUTHENTICATION_ENABLED:
    app.config[""SECRET_KEY""] = os.getenv(""SECRET_KEY"")
    app.config[""AUTH_USERNAME""] = os.getenv(""AUTH_USERNAME"")
    app.config[""AUTH_PASSWORD""] = os.getenv(""AUTH_PASSWORD"")
    from flask_httpauth import HTTPBasicAuth
    auth = HTTPBasicAuth()
    @auth.verify_password
    def verify_password(username, password):
        if username == app.config[""AUTH_USERNAME""] and password == app.config[""AUTH_PASSWORD""]:
            return True
        else:
            return False
    app.wsgi_app = auth.middleware(app.wsgi_app)

# Initialize the Flask application
if __name__ == ""__main__"":
    app.run()
