import json

class JSONObject:
    def __init__(self, data):
        self.data = data

    @staticmethod
    def from_json(json_string):
        return JSONObject(json.loads(json_string))

    def to_json(self):
        return json.dumps(self.data)

class FactoryRegistry:
    registry = {}

    @staticmethod
    def register_factory(id, factory):
        FactoryRegistry.registry[id] = factory

    @staticmethod
    def create_instance(id, *args, **kwargs):
        return FactoryRegistry.registry[id](*args, **kwargs)

class DerivedJSONObject(JSONObject):
    def __init__(self, data):
        super().__init__(data)
        self.additional_data = ""Additional data""

FactoryRegistry.register_factory(""derived_json"", DerivedJSONObject.from_json)

# Example usage:
json_object = JSONObject({""key"": ""value""})
print(json_object.to_json()) # Output: '{""key"": ""value""}'

derived_json_object = DerivedJSONObject({""key"": ""value""})
print(derived_json_object.to_json()) # Output: '{""key"": ""value"", ""additional_data"": ""Additional data""}'
```
