import json

class JSONObjectManager:
    def __init__(self):
        self.factories = {}

    def add_factory(self, id, func):
        self.factories[id] = func

    def create_from_json(self, json_string):
        data = json.loads(json_string)
        factory = self.factories.get(data['id'])
        if factory is None:
            raise ValueError(""Factory for ID '{}' not found"".format(data['id']))
        return factory(data)

    def to_json(self, obj):
        data = {
            'id': obj.id,
            'data': obj.to_dict()
        }
        return json.dumps(data)
```
