import json
from typing import Dict, Any

class JSONAdapter:
    def to_json(self):
        return json.dumps(self.__dict__)

    @staticmethod
    def from_json(json_str: str):
        data = json.loads(json_str)
        obj = JSONAdapter()
        for key, value in data.items():
            setattr(obj, key, value)
        return obj

class OctreeNode:
    def __init__(self, feature_sizes: List[int], prefix_leafs: List[str]):
        self.feature_sizes = feature_sizes
        self.prefix_leafs = prefix_leafs
        self.data = {}

    def add_data(self, key: str, value: Any):
        self.data[key] = value

    def get_data(self, key: str):
        return self.data[key]

    def to_json(self):
        json_dict = {}
        json_dict[""feature_sizes""] = self.feature_sizes
        json_dict[""prefix_leafs""] = self.prefix_leafs
        json_dict[""data""] = self.data
        return JSONAdapter.to_json(json_dict)

    @staticmethod
    def from_json(json_str: str):
        json_dict = json.loads(json_str)
        obj = OctreeNode(json_dict[""feature_sizes""], json_dict[""prefix_leafs""])
        for key, value in json_dict[""data""].items():
            obj.add_data(key, value)
        return obj

class NodeRegistry:
