      # initialize an empty dictionary to store the student names and their corresponding average grades
      new_dict = {}

      # loop through each student in the input dictionary
      for student, grade in student_dict.items():
          # compute the average grade for the current student
          avg_grade = sum(grade) / len(grade)

          # add the student name and their average grade to the new dictionary
          new_dict[student] = avg_grade

      return new_dict

  def sort_grades(new_dict):
      # initialize an empty list to store the sorted grades
      sorted_list = []

      # loop through each student in the input dictionary
      for student, grade in new_dict.items():
          # add the student name and their average grade to the sorted list
          sorted_list.append((student, grade))

      # sort the list based on the average grade in a descending order
      return sorted(sorted_list, key=lambda x: x[1], reverse=True)

  def main():
      # test the functions by calling them with some sample input
      student_dict = {'Alice': [90, 85, 92], 'Bob': [75, 80, 70], 'Charlie': [95, 90, 99]}

      new_dict = get_student_grades(student_dict)
      sorted_list = sort_grades(new_dict)

      # print the output
      for student, grade in sorted_list:
          print(f""{student}: {grade}"")

  if __name__ == ""__main__"":
