```python
import time

employees = {
    ""employee1"": 5000,
    ""employee2"": 6000,
    ""employee3"": 7000
}

def calculate_averages(employees):
    averages = {}
    for employee_id in employees:
        average = employees[employee_id] / 12
        averages[employee_id] = average
    return averages

def sort_averages(averages):
    sorted_averages = dict(sorted(averages.items(), key=lambda item: item[1], reverse=True))
    return sorted_averages

def display_menu():
    print(""Choose your attack:"")
    print(""1. Attack A"")
    print(""2. Attack B"")

def select_attack():
    choice = input(""Enter your choice (1 or 2): "")

def perform_attack(choice):
   if choice == ""1"":
       print(""\nPerforming Attack A...\n"")
   elif choice == ""2"":
       print(""\nPerforming Attack B...\n"")
   else:
       print(""Invalid choice. Please enter either 1 or 2."")

attack_cooldown_seconds = 9
last_performed = 0

def main():
    global last_performed
    while True:
        display_menu()
        select_attack()
        if time.time() > last_performed + attack_cooldown_seconds:
            perform_attack(choice)
            last_performed = time.time()

if __name__ == ""__main__"":
    main()
