import csv
import subprocess

def process_responses():
    # Read data from CSV file in batches
    with open('input.csv', 'r') as f:
        reader = csv.reader(f)
        batches = []
        for row in reader:
            batches.append(row)

    # Encode each batch of data into UTF-8 format
    encoded_data = []
    for batch in batches:
        for row in batch:
            encoded_data.append(row.encode('utf-8'))

    # Pass the encoded data along with required headers to the C function via subprocess call
    cmd = ['make_request', '-u', 'https://example.com', '-m', 'POST', '-H', 'Content-Type: application/json']
    for row in encoded_data:
        proc = subprocess.Popen(cmd + [row], stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        output = proc.communicate()[0]
        if proc.returncode != 0:
            print(""Error occurred while making request"")
        else:
            print(output.decode('utf-8'))

if __name__ == '__main__':
    process_responses()
