    id = db.Column(db.Integer, primary_key=True)
    data = db.Column(db.String(255))

def update_resource(resource_id, updated_data):
    try:
        resource = Resource.query.filter_by(id=resource_id).first()
        if not resource:
            return {""message"": ""Resource not found""}, 404

        resource.data = updated_data
        db.session.commit()
        return {""message"": ""Resource updated successfully""}, 200
    except Exception as e:
        db.session.rollback()
        return {""error"": str(e)}, 500

def get_resource(resource_id):
    try:
        resource = Resource.query.filter_by(id=resource_id).first()
        if not resource:
            return {""message"": ""Resource not found""}, 404

        serialized_resource = {
            ""id"": resource.id,
            ""data"": resource.data,
        }

        return serialized_resource, 200
    except Exception as e:
        return {""error"": str(e)}, 500

@app.route('/api/resources/<int:resource_id>', methods=['PUT'])
def put_resource(resource_id):
    updated_data = request.json.get('data')
    if not updated_data:
        return {""error"": ""Missing 'data' in request body""}, 400

    response, status_code = update_resource(resource_id, updated_data)
    return response, status_code

@app.route('/api/resources/<int:resource_id>', methods=['GET'])
def get_resource_route(resource_id):
    response, status_code = get_resource(resource_id)
    return response, status_code

if __name__ == '__main__':
    db.create_all()  
    app.run(debug=True)
```
This code snippet sets up a simple Flask application with two endpoints for updating and retrieving resources. The `update_resource` function handles PUT requests by fetching the target resource using its unique identifier (`resource_id`) and updating its data attribute with the updated data provided in the request body. The `get_resource` function handles GET requests by querying the database for a resource matching the provided `resource_id`, and returning it serialized as JSON if found, or an error message if not found.

The endpoints are defined using the `@app.route()` decorator, which maps URL paths to specific functions. The `methods` argument of the decorator specifies the HTTP methods that can be used to access the endpoint (e.g., GET for retrieval and PUT for update).

In the example code, the Flask application uses a SQLite database as its backend, and SQLAlchemy ORM is used to interact with the database. The `Resource` class defines the structure of the resource model, with an ID column and data attribute. The `update_resource` and `get_resource` functions are defined separately to handle PUT and GET requests, respectively.

