import os

def process_filenames(filenames):
    processed_filenames = []
    for filename in filenames:
        filetype = os.path.splitext(filename)[1].lower()
        if filetype == "".doc"":
            label = ""Microsoft Word""
        elif filetype == "".pdf"":
            label = ""Adobe PDF""
        elif filetype == "".xls"":
            label = ""Microsoft Excel""
        else:
            label = None
        special_chars = len(filename) - len(filetype)
        if label is not None:
            processed_filenames.append((f""{label} ({special_chars} special characters)"", filename))
    return processed_filenames
