def get_average_earnings(employee_data):
    # Initialize empty dictionary to store average earnings for each employee
    average_earnings = {}

    # Iterate through each employee in the input data
    for employee in employee_data:
        # Calculate total earnings for current employee
        total_earnings = sum(employee['earnings'])

        # Add current employee's average monthly earnings to dictionary
        average_earnings[employee['ID']] = total_earnings / 12

    # Sort employees by their average earnings in descending order
    sorted_employees = sorted(average_earnings.items(), key=lambda x: x[1], reverse=True)

    return sorted_employees

