# Function for processing files in memory or line by line
def processFile(filePath, chunkSize=1024):
  # Open the file and read its contents into a byte array
  with open(filePath, 'rb') as f:
    data = f.read()

  # Create a progress bar to monitor the hashing process
  progressBar = ProgressBar('Hashing files', len(data))

  # Initialize variables for tracking progress and errors
  totalChunks = int(len(data) / chunkSize) + (len(data) % chunkSize > 0)
  currentChunk = 1
  hashingErrors = []

  # Define a function to compute the MD5 hash of a chunk of data
  def computeHash(chunk):
    try:
      return hashlib.md5(chunk).hexdigest()
    except Exception as e:
      hashingErrors.append((filePath, currentChunk, str(e)))

  # Use multithreading to compute the MD5 hashes of each chunk concurrently
  threadPool = threading.ThreadPool(max_workers=4)
  results = []
  for i in range(0, len(data), chunkSize):
    results.append(threadPool.apply_async(computeHash, (data[i:i+chunkSize],)))

  # Wait for all threads to complete and handle potential errors
  threadPool.close()
  threadPool.join()
  for result in results:
    if result.get() is None:
      hashingErrors.append((filePath, currentChunk, 'Hashing error'))

  # Print a summary of the progress and any errors encountered
  print('Finished hashing {}: {}/{} chunks processed'.format(filePath, currentChunk, totalChunks))
  if len(hashingErrors) > 0:
    print('Hashing errors encountered:')
    for error in hashingErrors:
      print('File: {}, Chunk: {}, Error: {}'.format(*error))
