Firstly, create the `random_data_generator` function to produce random data according to specified parameters. Then, proceed with implementing the `sha256_hash` function. Following this, design the `calculate_directory_hashes` function which calculates hashes based on user preferences regarding file processing (in memory or chunk by chunk) and uses multiprocessing for efficiency. Ensure real-time progress tracking is integrated into each hashing process. Lastly, consider options for result storage such as local file or database persistence.",328,,"[""
Here's an example implementation of the above program:
```
import os
import hashlib
import multiprocessing
import time

# Random data generator function
def random_data_generator(size, seed=None):
    if seed is not None:
        random.seed(seed)
    return ''.join(random.choice(string.ascii_letters + string.digits) for _ in range(size))

# SHA-256 hash function
def sha256_hash(filepath):
    with open(filepath, 'rb') as f:
        data = f.read()
        return hashlib.sha256(data).hexdigest()

# Calculate directory hashes function
def calculate_directory_hashes(directory_path, in_memory=False, chunk_size=1024*1024, progress_tracking=True):
    start = time.time()
    directory_hashes = {}

    # Walk through the directory and calculate hashes for each file
    for root, dirs, files in os.walk(directory_path):
        for filename in files:
            filepath = os.path.join(root, filename)
            if progress_tracking:
                print(f'Calculating hash for {filepath}...', end='')
            if in_memory:
                data = open(filepath, 'rb').read()
                directory_hashes[filename] = sha256_hash(data)
            else:
                chunk_size = min(chunk_size, os.stat(filepath).st_size - 1)
                with open(filepath, 'rb') as f:
                    while True:
                        data = f.read(chunk_size)
                        if not data:
                            break
                        directory_hashes[filename] = sha256_hash(data)
                print('done!')

    # Print real-time progress tracking for each hashing process
    if progress_tracking:
        total_size = sum(os.stat(filepath).st_size for filepath in directory_hashes)
        for filename in directory_hashes:
            print(f'{filename}: {directory_hashes[filename]}')
        end = time.time()
        print(f'Done calculating hashes! Elapsed time: {end - start} seconds.')

    return directory_hashes

# Test the function with a random data generator and a sample directory
if __name__ == '__main__':
    directory = 'sample_directory'
    os.makedirs(directory, exist_ok=True)
    for filename in ['file1', 'file2', 'file3']:
        filepath = os.path.join(directory, filename)
        with open(filepath, 'wb') as f:
            f.write(random_data_generator(1024*1024, seed=filename))
    print('Files created!')
    directory_hashes = calculate_directory_hashes(directory, in_memory=False)
    print('Directory hashes calculated!')
```
Note that this is just an example implementation and you may need to adjust the code to fit your specific use case. Additionally, you should consider using a more robust data structure than a dictionary for storing the directory hashes, as it can become very large if the directory contains many files.""]",0,[0],[],False,1,0,0,"[{""block_id"": 1, ""language"": ""unknown"", ""error"": ""Unsupported language: unknown""}]"

