import hashlib
import hmac
import random
from Crypto.Cipher import AES

# Function to add support for the AES-128, AES-192, and AES-256 ciphers
def add_cipher_support(key_size):
    if key_size == 128:
        return AES.new(key, AES.MODE_CBC, IV)
    elif key_size == 192:
        return AES.new(key, AES.MODE_CBC, IV)
    elif key_size == 256:
        return AES.new(key, AES.MODE_CBC, IV)
    else:
        raise ValueError(""Unsupported cipher size"")

# Function to encrypt a message using the selected cipher
def encrypt_message(cipher, message):
    return cipher.encrypt(message)

# Function to decrypt a message using the selected cipher
def decrypt_message(cipher, message):
    return cipher.decrypt(message)

# Function to add support for SHA-256 hashing
def hash_message(message):
    return hashlib.sha256(message).hexdigest()

# Function to verify the integrity of the encrypted data using HMAC-SHA256
def verify_integrity(cipher, message):
    hmac = hmac.new(key, message, digestmod=hashlib.sha256)
    return cipher.decrypt(hmac).hexdigest() == hmac.hexdigest()

# Function to handle different cipher configurations based on user selection
def handle_cipher_config(selected_cipher):
    if selected_cipher == ""AES-128"":
        return add_cipher_support(128)
    elif selected_cipher == ""AES-192"":
        return add_cipher_support(192)
    elif selected_cipher == ""AES-256"":
        return add_cipher_support(256)
    else:
        raise ValueError(""Unsupported cipher selection"")

# Function to handle error handling mechanisms for unsupported ciphers or cryptographic failures
def handle_error(e):
    print(""An error occurred:"", e)

# Main function to demonstrate the use of different symmetric encryption algorithms in a secure messaging application
def main():
    key = b""this is a secret key""
    IV = random.getrandbits(128)
    selected_cipher = ""AES-256""
    message = ""This is a top-secret message.""

    try:
        cipher = handle_cipher_config(selected_cipher)
        encrypted_message = encrypt_message(cipher, message)
        decrypted_message = decrypt_message(cipher, encrypted_message)
        hashed_message = hash_message(encrypted_message)
        integrity_verified = verify_integrity(cipher, encrypted_message)

        print(""Original message:"", message)
        print(""Encrypted message:"", encrypted_message)
        print(""Decrypted message:"", decrypted_message)
        print(""Hashed message:"", hashed_message)
        print(""Integrity verified:"", integrity_verified)
    except ValueError as e:
        handle_error(e)
