import random

def generate_random_ipv4_addresses(num_devices):
    unique_ips = set()
    while len(unique_ips) < num_devices:
        ip = f""{random.randint(0, 255)}.{random.randint(0, 255)}.{random.randint(0, 255)}.{random.randint(0, 255)}""
        if not ip.startswith(""0.0.0.""):
            unique_ips.add(ip)
    return list(unique_ips)

def validate_ipv4_address(ip_address):
