        raise ValueError(""IP address must be a string"")
    parts = ip_address.split(""."")
    if len(parts) != 4:
        raise ValueError(""Invalid IP address format"")
    for part in parts:
        try:
            int(part)
        except ValueError:
            raise ValueError(""Invalid IP address format"")
        if not (0 <= int(part) <= 255):
            raise ValueError(""IP address out of range"")
    return True
