import os
from typing import Optional

def count_files(dir: str) -> int:
    return sum(1 for f in os.listdir(dir) if f.endswith("".txt""))

def print_usage():
    print(""Usage: ./script.py [options]"")
    print(""Options:"")
    print(""-h, --help\tShow usage information."")
    print(""-d\tdestination directory (required)"")
    print(""-n\ttotal number of .txt files"")

def main(argv):
    if len(argv) == 1:
        print_usage()
        sys.exit(0)

    destination_dir = None
    total_files = 0

    for i, arg in enumerate(argv[1:]):
        if arg == ""-h"" or arg == ""--help"":
            print_usage()
            sys.exit(0)
        elif arg == ""-d"":
            destination_dir = argv[i + 2]
        elif arg == ""-n"":
            total_files = count_files(destination_dir)

    if not destination_dir:
        print(""Error: Please specify a destination directory"")
        sys.exit(1)

    print(f""Total number of .txt files in {destination_dir}: {total_files}"")

if __name__ == ""__main__"":
