# Define a function to extract the file extension from a filename
def extract_file_extension(filename):
    return os.path.splitext(filename)[-1]

# Define a function to check if a filename has a valid extension for Microsoft Word documents ("".doc"")
def is_valid_doc_extension(filename):
    return extract_file_extension(filename) == "".doc""

# Define a function to check if a filename has a valid extension for Adobe PDF files ("".pdf"")
def is_valid_pdf_extension(filename):
    return extract_file_extension(filename) == "".pdf""

# Define a function to check if a filename has a valid extension for Microsoft Excel spreadsheets ("".xls"")
def is_valid_xls_extension(filename):
    return extract_file_extension(filename) == "".xls""

# Define a function to add a descriptive label based on the file type
def add_label(filename, label):
    if is_valid_doc_extension(filename):
        return f""{label} (Microsoft Word)""
    elif is_valid_pdf_extension(filename):
        return f""{label} (Adobe PDF)""
    elif is_valid_xls_extension(filename):
        return f""{label} (Microsoft Excel)""
    else:
        return label

# Define a function to count the number of special characters in a filename
