0,"Design a task that involves integrating an encryption algorithm into a software module for secure data transmission. The module should support both symmetric and asymmetric encryption methods, allowing users to encrypt and decrypt data using keys generated within the application. The task should include the implementation of key management features, such as key generation, storage, and retrieval. Additionally, the task should require the development of a user interface that enables users to easily manage encryption settings and perform secure data operations. The solution should also include comprehensive testing to ensure the security and reliability of the encryption features.",680,,"['package main
import (
	""crypto/aes""
	""crypto/cipher""
	""crypto/rand""
	""encoding/base64""
	""errors""
	""fmt""
)
type SymmetricEncryption struct {
	key []byte
}
func NewSymmetricEncryption(key []byte) (*SymmetricEncryption, error) {
	if len(key) != 32 {
		return nil, errors.New(""invalid key length"")
	}
	return &SymmetricEncryption{key: key}, nil
}
func (e *SymmetricEncryption) Encrypt(data []byte) ([]byte, error) {
	block, err := aes.NewCipher(e.key)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, gcm.NonceSize())
	_, err = rand.Read(nonce)
	if err != nil {
		return nil, err
	}
	ciphertext := gcm.Seal(nonce, nonce, data, nil)
	return ciphertext, nil
}
func (e *SymmetricEncryption) Decrypt(data []byte) ([]byte, error) {
	block, err := aes.NewCipher(e.key)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonceSize := gcm.NonceSize()
	nonce, ciphertext := data[:nonceSize], data[nonceSize:]
	plaintext, err := gcm.Open(nil, nonce, ciphertext, nil)
	if err != nil {
		return nil, err
	}
	return plaintext, nil
}
type AsymmetricEncryption struct {
	publicKey  *rsa.PublicKey
	privateKey *rsa.PrivateKey
}
func NewAsymmetricEncryption(publicKey *rsa.PublicKey, privateKey *rsa.PrivateKey) (*AsymmetricEncryption, error) {
	if publicKey == nil || privateKey == nil {
		return nil, errors.New(""invalid key pair"")
	}
	return &AsymmetricEncryption{publicKey: publicKey, privateKey: privateKey}, nil
}
func (e *AsymmetricEncryption) Encrypt(data []byte) ([]byte, error) {
	ciphertext, err := rsa.EncryptOAEP(sha256.New(), rand.Reader, e.publicKey, data, nil)
	if err != nil {
		return nil, err
	}
	return ciphertext, nil
}
func (e *AsymmetricEncryption) Decrypt(data []byte) ([]byte, error) {
	plaintext, err := rsa.DecryptOAEP(sha256.New(), rand.Reader, e.privateKey, data, nil)
	if err != nil {
		return nil, err
	}
	return plaintext, nil
}
