1,"Create a Python program that utilizes a dynamic linked list to manage a collection of nodes representing network devices in a distributed system. The nodes will store information about each device, such as its IP address, current status (online/offline), and last known timestamp. Implement functions for adding new nodes to the list, removing existing nodes, updating node status, and searching for specific nodes by IP address. Additionally, incorporate a method to generate random delays between node updates to simulate varying network latencies in real-world scenarios.",589,,"[""```
import random

class Node:
    def __init__(self, ip_address, status, last_updated):
        self.ip_address = ip_address
        self.status = status
        self.last_updated = last_updated

class NetworkDeviceList:
    def __init__(self):
        self.nodes = []

    def add_node(self, ip_address, status='online', last_updated=None):
        if last_updated is None:
            last_updated = datetime.datetime.now()
        node = Node(ip_address, status, last_updated)
        self.nodes.append(node)

    def remove_node(self, ip_address):
        for node in self.nodes:
            if node.ip_address == ip_address:
                self.nodes.remove(node)
                return True
        return False

    def update_node_status(self, ip_address, new_status):
        for node in self.nodes:
            if node.ip_address == ip_address:
                node.status = new_status
                node.last_updated = datetime.datetime.now()
                return True
        return False

    def search_node(self, ip_address):
        for node in self.nodes:
            if node.ip_address == ip_address:
                return node
        return None

    def simulate_random_delay(self):
        delay = random.randint(100, 500) / 1000
        time.sleep(delay)

if __name__ == '__main__':
    network_list = NetworkDeviceList()
    for i in range(10):
        ip_address = f'192.168.{i}.1'
        status = 'online' if i % 2 == 0 else 'offline'
        last_updated = datetime.datetime.now() - datetime.timedelta(minutes=i)
        network_list.add_node(ip_address, status, last_updated)

    while True:
        print('Network devices:')
        for node in network_list.nodes:
            print(f'{node.ip_address}: {node.status} - Last updated: {node.last_updated}')
        network_list.simulate_random_delay()
