The script provides a versatile tool for efficiently computing MD5 hash values across numerous files in parallel with detailed progress tracking capabilities.",680,,"['```
import os
import threading
import hashlib
from tqdm import tqdm

class MD5Hasher:
    def __init__(self, chunk_size=64*1024):
        self.chunk_size = chunk_size
        self.hasher = hashlib.md5()

    def process_file(self, filename):
        if not os.path.exists(filename) or not os.access(filename, os.R_OK):
            raise FileNotFoundError(""File not found or not readable: {}"".format(filename))

        with open(filename, ""rb"") as f:
            chunk = f.read(self.chunk_size)
            while chunk:
                self.hasher.update(chunk)
                chunk = f.read(self.chunk_size)

    def hash_files(self, filenames):
        if not isinstance(filenames, list):
            raise ValueError(""filenames must be a list of strings"")

        threads = []
        for filename in tqdm(filenames, desc=""Hashing files"", unit=""file""):
            thread = threading.Thread(target=self.process_file, args=(filename,))
            thread.start()
            threads.append(thread)

        for thread in threads:
            thread.join()

    def get_hash(self):
        return self.hasher.hexdigest()
