import hashlib
import secrets

def generate_random_string(length: int, char_set: str = ""abcdefghijklmnopqrstuvwxyz0123456789"") -> str:
    return """".join([secrets.choice(char_set) for _ in range(length)])

def hash_password(password: str, salt: bytes = None) -> str:
    if not salt:
        salt = secrets.token_bytes(16)
    hashed_password = hashlib.sha256(salt + password.encode()).hexdigest()
    return f""{hashed_password}{salt.hex()}""

def modify_filename_extension(filepath: str, new_extension: str):
    if filepath.endswith("".txt"") or filepath.endswith("".doc""):
        random_string = generate_random_string(10)
        return f""{filepath}.{new_extension}_{random_string}""
    else:
        return filepath
