import pytest
from data_processor import DataProcessor

def test_generate_random_integer():
    dp = DataProcessor()
    assert dp.generate_random_integer(0, 10) in range(10)

def test_generate_random_float():
    dp = DataProcessor()
    assert dp.generate_random_float(0, 10) in range(10)

def test_compute_statistics():
    dp = DataProcessor([1, 2, 3, 4])
    mean, median, mode, standard_deviation = dp.compute_statistics()
    assert mean == 2.5
    assert median == 2.5
    assert mode == 3
    assert standard_deviation == 1.27269330784

def test_filter_data():
    dp = DataProcessor([1, 2, 3, 4])
    filtered_data = dp.filter_data(lambda x: x > 2)
    assert filtered_data == [3, 4]

def test_sort_data():
    dp = DataProcessor([1, 2, 3, 4])
    sorted_data = dp.sort_data()
    assert sorted_data == [1, 2, 3, 4]

def test_reverse_order():
    dp = DataProcessor([1, 2, 3, 4])
    reversed_data = dp.reverse_order()
    assert reversed_data == [4, 3, 2, 1]
