import random
import time
from datetime import datetime

class SensorData:
    def __init__(self, sensor_id, timestamp, value):
        self.sensor_id = sensor_id
        self.timestamp = timestamp
        self.value = value

    def validate(self):
        if self.sensor_id < 0 or self.sensor_id > 10:
            raise ValueError(""Sensor ID out of range"")
        if self.timestamp < datetime.now() - timedelta(days=365):
            raise ValueError(""Timestamp is too old"")
        if self.value < 0 or self.value > 100:
            raise ValueError(""Value out of range"")

def generate_sensor_data(n, min_id=-1, max_id=10, min_ts=datetime.now() - timedelta(days=365), max_ts=datetime.now(), min_val=0, max_val=100):
    sensor_data = []

    # Generate random sensor IDs and timestamps within the specified range
    for i in range(n):
