```
class Library:
    def __init__(self, initial_books=0):
        self.books = []
        self.initial_books = initial_books

    def add_book(self, title, author, publisher, publication_date):
        book = {
            'title': title,
            'author': author,
            'publisher': publisher,
            'publication_date': publication_date
        }
        self.books.append(book)

    def remove_book(self, title):
        for book in self.books:
            if book['title'] == title:
                self.books.remove(book)
                break

    def display_all_books(self):
        for book in self.books:
            print(""{} by {}"".format(book['title'], book['author']))

    def search_book_by_title(self, title):
        for book in self.books:
            if book['title'] == title:
                return book
        return None

    def exit(self):
        print(""All operations completed."")
        raise SystemExit
```
