import random
from typing import List
from ctypes import *

class AESHelper:
    def __init__(self, key_length=16, iv_range=2**32-1):
        self.key_length = key_length
        self.iv_range = iv_range

    @staticmethod
    def generateKeyArray(size):
        keys = []
        for _ in range(size):
            key = bytearray(self.key_length)
            random.seed()
            for i, char in enumerate(key):
                if random.randint(0, 2**8-1) < self.iv_range:
                    char = random.randint(0, 2**8-1)
            keys.append((key, random.randint(0, self.iv_range), bool(random.getrandbits(1))))
        return keys

    @staticmethod
    def convertToBytes(key):
        key_bytes = bytearray(self.key_length)
        for i, char in enumerate(key):
            key_bytes[i] = ord(char)
        return key_bytes

    @staticmethod
    def aesEncrypt(data):
        try:
            from OpenSSL import AES
            cipher = AES.new(self.convertToBytes(key), mode=AES.MODE_CBC, IV=random.getrandbits(1))
            return cipher.encrypt(data)
        except Exception as e:
            raise RuntimeError(f""Error occurred while encrypting data: {e}"")

    def encryptKeyArray(self, keys):
        encrypted_keys = []
        for key in keys:
            try:
                encrypted_key = self.aesEncrypt(self.convertToBytes(key))
                encrypted_keys.append((encrypted_key, key[1], key[2]))
            except Exception as e:
                raise RuntimeError(f""Error occurred while encrypting key: {e}"")
        return encrypted_keys
