def calculate_median(data_list):
    if not isinstance(data_list, list):
        raise ValueError(""Input must be a list of integers"")
    for element in data_list:
        if not isinstance(element, int):
            raise ValueError(""List contains non-integer elements"")
    if len(data_list) == 0:
        return float(""NaN"")
    sorted_list = sorted(data_list)
    middle_index = len(sorted_list) // 2
    if len(sorted_list) % 2 == 0:
        median = (sorted_list[middle_index - 1] + sorted_list[middle_index]) / 2
    else:
        median = sorted_list[middle_index]
    return float(median)

def test_calculate_median():
    assert calculate_median([]) == float(""NaN"")
    assert calculate_median([0]) == 0.0
    assert calculate_median([1, 2, 3]) == 2.0
    assert calculate_median([1, 2, 3, 4, 5]) == 3.0
    assert calculate_median([1, 2, 3, 4, 5, 6]) == 3.5
    assert calculate_median([1, 2, 3, 4, 5, 6, 7]) == 4.0
    assert calculate_median([1, 2, 3, 4, 5, 6, 7, 8]) == 4.5
