import csv
import logging
from typing import List, Dict

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Define the function for handling errors
def handle_error(response: Dict[str, str]) -> None:
  if ""status"" in response and response[""status""] == ""error"":
    logger.error(""Error occurred!"")

# Define the function for reading CSV data and processing it
def read_csv(filepath: str) -> List[Dict[str, str]]:
  with open(filepath) as csv_file:
    reader = csv.reader(csv_file)
    data = []
    for row in reader:
      data.append({""name"": row[0], ""age"": row[1]})
    return data

# Define the function for sending API requests
def send_request(url: str, method: str, headers: Dict[str, str], payload: Dict[str, str]) -> None:
  try:
    # Set the URL and HTTP method
    response = requests.request(method, url, headers=headers, json=payload)

    # Check for errors
    handle_error(response.json())

    # Print the response
    print(response.json())
  except requests.exceptions.RequestException as e:
    logger.error(""Error sending API request!"", exc_info=True)

# Define the main function
def main() -> None:
  # Read CSV data and process it
  data = read_csv(""data.csv"")
  for row in data:
    name = row[""name""]
    age = int(row[""age""])
    url = ""https://example.com/api""
    method = ""POST""
    headers = {""Content-Type"": ""application/json""}
    payload = {""name"": name, ""age"": age}
    send_request(url, method, headers, payload)

# Call the main function
if __name__ == ""__main__"":
  main()

