        self.node_id = node_id
        self.node_status = node_status
        self.node_type = node_type
        self.node_priority = node_priority

def create_array(size, node_id_start=0):
    array = []
    for i in range(size):
        node_id = random.randint(node_id_start, node_id_start + size - 1)
        node_status = random.choice(['Up', 'Down'])
        node_type = random.choice(['Master', 'Slave'])
        node_priority = _get_node_priority(node_status, node_type)
        array.append(NodeAttribute(node_id, node_status, node_type, node_priority))
    return array

def _get_node_priority(node_status, node_type):
    if node_status == 'Up':
        if node_type == 'Master':
            return 10
        else:
            return 5
    else:
        return 0
